class SyntaxNode {
    constructor(nodeName, children) {
        this.name = nodeName;
        this.children = children;
    }

    toString() {
        const childrenToString = this.children
            .map(child => {
                    return child.toString()
                }
            ).join(", ");

        if (this.children.length > 0)
            return `${this.name}: [${childrenToString}]`;
        
        return `${this.name}`;
    }
}

